n                            end\n                        end\n                    endcase\n                end\n\n                S_DONE: begin\n                    result <= 1'b1;\n                    status <= 2'b01;\n                    done <= 1'b1;\n                    state <= S_IDLE;\n                end\n\n                S_FAIL: begin\n                    result <= 1'b0;\n                    status <= 2'b10;\n                    done <= 1'b1;\n                    state <= S_IDLE;\n                end\n            endcase\n        end\n    end\nendmodule"
